'use strict';

function flushJobs(seed, expand, maxJobs) {
  if (!Array.isArray(seed) || seed.some(job => typeof job !== 'string')) {
    throw new TypeError('seed must contain strings');
  }
  if (typeof expand !== 'function') throw new TypeError('expand must be a function');
  if (!Number.isSafeInteger(maxJobs) || maxJobs < 0) {
    throw new TypeError('maxJobs must be a non-negative safe integer');
  }

  const queue = seed.slice();
  const processed = [];
  const initiallyScheduled = queue.length;
  let cursor = 0;
  while (cursor < initiallyScheduled && processed.length < maxJobs) {
    const job = queue[cursor++];
    const generated = expand(job);
    if (!Array.isArray(generated) || generated.some(item => typeof item !== 'string')) {
      throw new TypeError('expand must return an array of strings');
    }
    processed.push(job);
    queue.push(...generated);
  }
  return { processed, pending: queue.slice(cursor) };
}

module.exports = { flushJobs };
```

