'use strict';

const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['flushJobs']);
const { flushJobs } = api;

const seed = ['a', 'b'];
const calls = [];
const result = flushJobs(seed, job => {
  calls.push(job);
  if (job === 'a') return ['c', 'd'];
  if (job === 'b') return ['e'];
  return [];
}, 4);
assert.deepStrictEqual(calls, ['a', 'b', 'c', 'd']);
assert.deepStrictEqual(result, {
  processed: ['a', 'b', 'c', 'd'],
  pending: ['e']
});
assert.deepStrictEqual(seed, ['a', 'b']);
assert.notStrictEqual(result.processed, seed);
assert.notStrictEqual(result.pending, seed);

let zeroCalls = 0;
assert.deepStrictEqual(flushJobs(seed, () => { zeroCalls += 1; return []; }, 0), {
  processed: [], pending: ['a', 'b']
});
assert.strictEqual(zeroCalls, 0);
assert.deepStrictEqual(flushJobs([], () => [], 10), { processed: [], pending: [] });

const generated = ['child'];
assert.deepStrictEqual(flushJobs(['root'], () => generated, 1), {
  processed: ['root'], pending: ['child']
});
assert.deepStrictEqual(generated, ['child']);

assert.deepStrictEqual(flushJobs(['x'], job => job === 'x' ? ['y'] : ['z'], 3), {
  processed: ['x', 'y', 'z'], pending: ['z']
});

for (const badSeed of [null, {}, ['ok', 1]]) {
  assert.throws(() => flushJobs(badSeed, () => [], 1), TypeError);
}
assert.throws(() => flushJobs([], null, 1), TypeError);
for (const badMax of [-1, 1.5, Number.MAX_SAFE_INTEGER + 1, '1']) {
  assert.throws(() => flushJobs([], () => [], badMax), TypeError);
}
for (const badGenerated of [null, {}, ['ok', 1]]) {
  assert.throws(() => flushJobs(['job'], () => badGenerated, 1), TypeError);
}

